def deBlasiSet (A : Set E) : ℝ :=
  sInf {ε : ℝ | 0 < ε ∧ ∃ D : Set E, IsCompact (toWeakSpace 𝕜 E '' D) ∧
    ∀ x ∈ A, ∃ y ∈ D, ‖x - y‖ ≤ ε}

